:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --card-back: #533483;
  --card-back-hover: #6a4b9a;
  --card-border: #eaeaea;
  --font: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
  width: 100%;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.stats {
  font-size: 1.125rem;
  color: #b0b0c0;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  width: 100%;
  max-width: 480px;
  aspect-ratio: 1 / 1;
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  border: 3px solid var(--card-border);
  background: var(--card-back);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  user-select: none;
  position: relative;
}

.card:hover:not(.flipped):not(.matched) {
  background: var(--card-back-hover);
  transform: scale(1.03);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:active:not(.flipped):not(.matched) {
  transform: scale(0.97);
}

.card.flipped,
.card.matched {
  background: var(--flipped-color, #fff);
  border-color: var(--card-border);
  cursor: default;
}

.card.matched {
  box-shadow: 0 0 12px rgba(233, 69, 96, 0.6);
  animation: pulse 0.4s ease;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

.card::after {
  content: '?';
  color: #fff;
  font-weight: bold;
  font-size: 1.5rem;
}

.card.flipped::after,
.card.matched::after {
  content: '';
}

.win-message {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--accent);
  text-align: center;
  padding: 12px 24px;
  background: rgba(233, 69, 96, 0.1);
  border-radius: 12px;
  border: 2px solid var(--accent);
  width: 100%;
}

.new-game-btn {
  font-family: var(--font);
  font-size: 1.125rem;
  font-weight: bold;
  padding: 12px 32px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  letter-spacing: 1px;
}

.new-game-btn:hover {
  background: #ff5a7a;
  box-shadow: 0 4px 16px rgba(233, 69, 96, 0.4);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
    gap: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .board {
    gap: 6px;
  }
  .card {
    border-width: 2px;
    border-radius: 6px;
  }
  .card::after {
    font-size: 1.2rem;
  }
}

const COLORS = [
  '#e94560', '#ff9f1c', '#2ec4b6', '#3a86ff',
  '#8338ec', '#06d6a0', '#ef476f', '#ffd166'
];

const board = document.getElementById('board');
const movesEl = document.getElementById('moves');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game');

let firstCard = null;
let secondCard = null;
let lockBoard = false;
let moves = 0;
let matchedPairs = 0;

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function createBoard() {
  board.innerHTML = '';
  const deck = shuffle([...COLORS, ...COLORS]);
  deck.forEach((color, index) => {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.color = color;
    card.dataset.index = index;
    card.setAttribute('aria-label', `Card ${index + 1}, face down`);
    card.addEventListener('click', flipCard);
    board.appendChild(card);
  });
}

function flipCard() {
  if (lockBoard) return;
  const card = this;
  if (card === firstCard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.style.setProperty('--flipped-color', card.dataset.color);
  card.setAttribute('aria-label', `Card ${parseInt(card.dataset.index) + 1}, revealed`);

  if (!firstCard) {
    firstCard = card;
    return;
  }

  secondCard = card;
  lockBoard = true;
  moves++;
  movesEl.textContent = `Moves: ${moves}`;

  if (firstCard.dataset.color === secondCard.dataset.color) {
    firstCard.classList.add('matched');
    secondCard.classList.add('matched');
    firstCard.setAttribute('aria-label', `Card ${parseInt(firstCard.dataset.index) + 1}, matched`);
    secondCard.setAttribute('aria-label', `Card ${parseInt(secondCard.dataset.index) + 1}, matched`);
    matchedPairs++;
    resetTurn();
    if (matchedPairs === COLORS.length) {
      winMessage.hidden = false;
    }
  } else {
    setTimeout(() => {
      firstCard.classList.remove('flipped');
      secondCard.classList.remove('flipped');
      firstCard.style.removeProperty('--flipped-color');
      secondCard.style.removeProperty('--flipped-color');
      firstCard.setAttribute('aria-label', `Card ${parseInt(firstCard.dataset.index) + 1}, face down`);
      secondCard.setAttribute('aria-label', `Card ${parseInt(secondCard.dataset.index) + 1}, face down`);
      resetTurn();
    }, 800);
  }
}

function resetTurn() {
  firstCard = null;
  secondCard = null;
  lockBoard = false;
}

function newGame() {
  firstCard = null;
  secondCard = null;
  lockBoard = false;
  moves = 0;
  matchedPairs = 0;
  movesEl.textContent = 'Moves: 0';
  winMessage.hidden = true;
  createBoard();
}

newGameBtn.addEventListener('click', newGame);

createBoard();
